export const ERRORS = [{"code":"ORA-00001","title":"Unique constraint violated","cause":"An INSERT or UPDATE tried to store a value that already exists in a column (or column set) protected by a PRIMARY KEY or UNIQUE constraint or a unique index. The error text names the constraint (owner.constraint_name).","action":"Find the constraint: SELECT table_name, column_name FROM all_cons_columns WHERE constraint_name = '<name>'. Then check for the existing row, use a sequence/identity for generated keys, or use MERGE when the row may already exist. In bulk loads, DML error logging (LOG ERRORS INTO) lets the good rows through."},{"code":"ORA-00054","title":"Resource busy and acquire with NOWAIT specified or timeout expired","cause":"The statement needs a lock on a row or table that another session holds, and it was told not to wait (NOWAIT, DDL against a table with open transactions, or DDL_LOCK_TIMEOUT expired).","action":"Find the blocker in v$session (blocking_session column) or v$locked_object and let it commit or roll back. For DDL on busy tables set ALTER SESSION SET ddl_lock_timeout = 30, or run it in a quiet window. Uncommitted work in your own other session (IDE tab) is a frequent cause."},{"code":"ORA-00060","title":"Deadlock detected while waiting for resource","cause":"Two sessions each hold a lock the other one needs. Oracle detects the cycle and rolls back the current statement of one of them (not the whole transaction). A trace file with the deadlock graph is written to the diagnostic directory.","action":"Make all code paths lock rows in the same order (for example ORDER BY primary key in SELECT ... FOR UPDATE). Index foreign key columns: unindexed foreign keys are the classic cause of deadlocks when parent rows are deleted or their keys updated. Keep transactions short and commit or roll back after the error."},{"code":"ORA-00904","title":"Invalid identifier","cause":"A column, alias or function name in the statement does not exist or is not visible at that point: typo, column missing in that table, a column alias used in WHERE/GROUP BY of the same query level, or a name created in quotes with different case (\"MyCol\" vs MYCOL).","action":"Check the spelling against ALL_TAB_COLUMNS. Column aliases from the SELECT list can only be used in ORDER BY (wrap the query in an inline view to filter on them). If the object was created with quoted mixed-case names you must quote them every time."},{"code":"ORA-00907","title":"Missing right parenthesis","cause":"The parser reached a point where it expected \")\" and found something else. Usually the real problem is earlier: a syntax error inside the parentheses (bad datatype in CREATE TABLE, ORDER BY inside an IN subquery, missing comma, wrong keyword).","action":"Look at the content of the parenthesised block, not only at the brackets. Common cases: ORDER BY in a subquery used with IN, constraint clause written in the wrong place, VARCHAR2 without length, unsupported syntax for your database version."},{"code":"ORA-00911","title":"Invalid character","cause":"The statement contains a character the SQL parser does not accept: very often a trailing semicolon sent through JDBC/ODBC/EXECUTE IMMEDIATE, a smart quote copied from a document, or a non-ASCII character in an identifier.","action":"Remove the trailing \";\" from SQL executed by an application or EXECUTE IMMEDIATE (PL/SQL blocks keep their final \";\" and END). Replace typographic quotes with straight quotes. Quote identifiers that need special characters."},{"code":"ORA-00913","title":"Too many values","cause":"The number of values is larger than the number of target columns: INSERT ... VALUES / INSERT ... SELECT with more expressions than columns, or a subquery that returns more columns than the comparison expects.","action":"List the target columns explicitly in INSERT (INSERT INTO t (a, b) VALUES ...) and count both sides. For subqueries compare the column count on both sides of IN / = ."},{"code":"ORA-00917","title":"Missing comma","cause":"The parser expected a comma between items, usually in a VALUES list, a column list or a function call.","action":"Check the list near the reported position for a missing comma, an unquoted string literal, or a misplaced keyword."},{"code":"ORA-00918","title":"Column ambiguously defined","cause":"A column name exists in more than one table of the join and the statement does not say which one (in SELECT, WHERE, ORDER BY, or in the inner select of a query wrapped by ROWNUM pagination).","action":"Prefix the column with a table alias (e.alias.col) everywhere it appears. With ANSI JOIN ... USING do not qualify the USING column."},{"code":"ORA-00920","title":"Invalid relational operator","cause":"A WHERE/ON condition has an incomplete or unsupported comparison, for example a missing operator, \"= =\", or a boolean expression used where Oracle SQL expects a comparison (before 23ai SQL has no BOOLEAN conditions such as WHERE flag).","action":"Write a full comparison: WHERE flag = 'Y', WHERE x IS NULL, WHERE a BETWEEN b AND c. Check for a stray character between operands."},{"code":"ORA-00923","title":"FROM keyword not found where expected","cause":"The SELECT list is malformed so the parser never reaches FROM in the place it expects it: missing comma between columns, alias with spaces not in double quotes, reserved word used as an alias, or a missing FROM (use FROM dual).","action":"Check the commas in the SELECT list, put aliases with spaces in double quotes, and add FROM dual for SELECTs without a table (before Oracle 23ai)."},{"code":"ORA-00932","title":"Inconsistent datatypes","cause":"Two expressions that must have compatible types do not: comparing a CLOB with =, using a CLOB in DISTINCT/GROUP BY/ORDER BY/UNION, mixing a number and a date, or the error says \"expected X got Y\".","action":"Convert explicitly (TO_CHAR, TO_NUMBER, TO_DATE). For CLOBs use DBMS_LOB.COMPARE / DBMS_LOB.SUBSTR or compare a hash, and avoid CLOB columns in set operations and GROUP BY."},{"code":"ORA-00933","title":"SQL command not properly ended","cause":"The statement has extra text after a complete command: a clause in the wrong order, AS before a table alias (allowed for columns, not tables), ORDER BY in an INSERT ... SELECT subquery, or an UPDATE ... JOIN written in another database's syntax.","action":"Remove AS before table aliases, check the clause order (WHERE, GROUP BY, HAVING, ORDER BY), and rewrite UPDATE/DELETE with a join as MERGE or a correlated subquery."},{"code":"ORA-00936","title":"Missing expression","cause":"A required expression is empty: a trailing comma in the SELECT list, \"SELECT FROM\", an operator without its right-hand side, or a bind placeholder the driver did not replace.","action":"Look for a comma before FROM, empty parentheses, or a concatenated dynamic SQL string where a variable was empty."},{"code":"ORA-00937","title":"Not a single-group group function","cause":"The SELECT list mixes aggregate functions (SUM, COUNT, MAX...) with plain columns, but there is no GROUP BY.","action":"Add every non-aggregated column of the SELECT list to GROUP BY, or use an analytic function (SUM(x) OVER ()) if you want the total next to each row."},{"code":"ORA-00942","title":"Table or view does not exist","cause":"The object is missing, is in another schema, or you do not have a privilege on it (Oracle reports missing privileges as \"does not exist\" so it does not reveal the object). In PL/SQL, privileges granted through a role are not visible inside definer-rights stored code.","action":"Check ALL_OBJECTS for the name and owner, prefix it with the schema or create a synonym, and grant SELECT/INSERT/... directly to the user (not through a role) when the object is used inside a procedure or package. Watch for quoted lower-case table names."},{"code":"ORA-00947","title":"Not enough values","cause":"The opposite of ORA-00913: fewer values than target columns in INSERT, or fewer columns in a subquery than the comparison needs.","action":"List the target columns explicitly and make both sides the same length."},{"code":"ORA-00955","title":"Name is already used by an existing object","cause":"CREATE tried to use a name that already exists in the schema; tables, views, sequences, synonyms, procedures and packages share one namespace.","action":"Use CREATE OR REPLACE for code objects and views, drop or rename the existing object, or pick another name. In deployment scripts check ALL_OBJECTS first or catch the error."},{"code":"ORA-00979","title":"Not a GROUP BY expression","cause":"An expression in the SELECT list, HAVING or ORDER BY is neither aggregated nor exactly listed in GROUP BY.","action":"Add the expression to GROUP BY exactly as written in SELECT (column aliases are not allowed in GROUP BY before Oracle 23ai), or aggregate it (MAX(col))."},{"code":"ORA-01000","title":"Maximum open cursors exceeded","cause":"A session has more open cursors than the OPEN_CURSORS parameter allows. Almost always a leak: application code that does not close ResultSet/Statement objects, or PL/SQL that opens explicit cursors / ref cursors in a loop without closing them.","action":"Close statements and result sets in finally / try-with-resources, close explicit and REF cursors in PL/SQL (also in the exception handler). Find the leaking SQL with v$open_cursor for the session. Raising OPEN_CURSORS only hides a leak."},{"code":"ORA-01017","title":"Invalid username/password; logon denied","cause":"The credentials were rejected. Since 11g passwords are case-sensitive; the user may also be connecting to the wrong service/PDB, or the password file / OS authentication is not set up.","action":"Check the case of the password, the service name and PDB, and whether the account exists (DBA_USERS). Quote passwords containing special characters. On newer versions also check the client/server authentication protocol (see ORA-28040)."},{"code":"ORA-01400","title":"Cannot insert NULL into (column)","cause":"An INSERT left a NOT NULL column empty, either explicitly with NULL or by omitting a column that has no DEFAULT.","action":"Provide the value, add a DEFAULT (or DEFAULT ON NULL) to the column, or fill it in a trigger. The message names the schema, table and column."},{"code":"ORA-01403","title":"No data found","cause":"A SELECT ... INTO returned no row, a collection element that was never assigned (or was deleted) was read, or UTL_FILE reached end of file. In SQL called from PL/SQL functions it can silently become NULL.","action":"Handle it explicitly: BEGIN SELECT ... INTO ...; EXCEPTION WHEN NO_DATA_FOUND THEN ... END; or use an aggregate (MAX) / cursor loop when \"no row\" is normal. For collections check .EXISTS(i) first."},{"code":"ORA-01407","title":"Cannot update (column) to NULL","cause":"An UPDATE set a NOT NULL column to NULL, typically through a correlated subquery that found no row for some target rows.","action":"Add WHERE EXISTS (same subquery) to the UPDATE, or use NVL/COALESCE in the SET, or rewrite as MERGE."},{"code":"ORA-01422","title":"Exact fetch returns more than requested number of rows","cause":"A SELECT ... INTO returned more than one row (TOO_MANY_ROWS).","action":"Make the WHERE clause unique (use the key), aggregate, add FETCH FIRST 1 ROW ONLY / ROWNUM = 1 if any row is acceptable, or use BULK COLLECT into a collection."},{"code":"ORA-01427","title":"Single-row subquery returns more than one row","cause":"A subquery used with =, <, > or in the SELECT list returned more than one row.","action":"Use IN / EXISTS instead of =, add the missing join condition to the subquery, or aggregate it. Find the duplicates with GROUP BY ... HAVING COUNT(*) > 1."},{"code":"ORA-01438","title":"Value larger than specified precision allowed for this column","cause":"A number does not fit the column's NUMBER(p,s) definition, for example 1000 in NUMBER(3) or 12.5 in NUMBER(3,2).","action":"Check the column precision (precision minus scale = digits before the decimal point), widen the column or round/validate the value before storing it."},{"code":"ORA-01476","title":"Divisor is equal to zero","cause":"A division by zero in SQL or PL/SQL.","action":"Use NULLIF(divisor, 0) so the result is NULL, or CASE WHEN divisor = 0 THEN ... END."},{"code":"ORA-01722","title":"Invalid number","cause":"A string could not be converted to a number. Very often caused by implicit conversion: comparing a VARCHAR2 column holding some non-numeric values with a number (WHERE code = 123), so the error depends on the execution plan and data.","action":"Compare strings with strings (WHERE code = '123'), or convert safely with TO_NUMBER(x DEFAULT NULL ON CONVERSION ERROR) (12.2+) / VALIDATE_CONVERSION. Check NLS decimal separator for values like '1,5'."},{"code":"ORA-01830","title":"Date format picture ends before converting entire input string","cause":"The input string is longer than the format mask: for example a time part in the string but not in the mask, or relying on the session NLS_DATE_FORMAT.","action":"Give TO_DATE/TO_TIMESTAMP a mask that covers the whole input ('YYYY-MM-DD HH24:MI:SS'), or use DATE '2026-01-31' / TIMESTAMP literals."},{"code":"ORA-01843","title":"Not a valid month","cause":"The month part of the input does not match the format: wrong mask, wrong NLS_DATE_LANGUAGE for month names, or day and month swapped.","action":"Always pass an explicit mask, and for month names also the language: TO_DATE(s, 'DD-MON-YYYY', 'NLS_DATE_LANGUAGE=ENGLISH')."},{"code":"ORA-01861","title":"Literal does not match format string","cause":"The input string does not have the shape of the format mask (different separators, missing parts), often because no mask was given and the session NLS_DATE_FORMAT differs from the data.","action":"Pass a mask that matches the data exactly, or use DATE/TIMESTAMP literals. Never rely on implicit date conversion."},{"code":"ORA-02291","title":"Integrity constraint violated - parent key not found","cause":"An INSERT/UPDATE on a child table refers to a parent key value that does not exist.","action":"Insert the parent row first (or in the same transaction with a deferrable constraint), and check the value for typos or wrong type conversions. The message names the foreign key constraint."},{"code":"ORA-02292","title":"Integrity constraint violated - child record found","cause":"A DELETE (or key UPDATE) of a parent row is blocked because child rows still reference it.","action":"Delete the child rows first, or define the foreign key with ON DELETE CASCADE / SET NULL if that is the intended behaviour. The message names the foreign key constraint so you can find the child table."},{"code":"ORA-04091","title":"Table is mutating, trigger/function may not see it","cause":"A row-level trigger (or a function called from DML) reads or modifies the table that the triggering statement is changing.","action":"Use a compound trigger: collect the keys in the row-level section and do the work in AFTER STATEMENT. Or move the logic into the calling procedure. Avoid PRAGMA AUTONOMOUS_TRANSACTION as a workaround: the autonomous transaction cannot see the uncommitted changes of the triggering statement, so it works on stale data."},{"code":"ORA-06502","title":"PL/SQL: numeric or value error","cause":"A value does not fit a PL/SQL variable: string longer than the VARCHAR2 size (character string buffer too small), number out of range or precision, NULL assigned to a NOT NULL variable, or a string-to-number conversion failure.","action":"Read the suffix of the message (character string buffer too small / character to number conversion error / number precision too large). Declare variables with %TYPE so they follow the column size, and remember VARCHAR2 sizes default to BYTE semantics with multi-byte character sets."},{"code":"ORA-06508","title":"PL/SQL: could not find program unit being called","cause":"A called unit is missing or invalid at run time, often because a package was recompiled or dropped while the session held its state, or a dependency is invalid.","action":"Recompile invalid objects (UTL_RECOMP or ALTER ... COMPILE), check ALL_ERRORS, and reconnect sessions that cached the old state. Check privileges on the called unit."},{"code":"ORA-06512","title":"At line (error stack location)","cause":"Not an error by itself: it is a stack line telling where the error above it happened (\"at owner.unit, line N\"). The real error is the first ORA- code in the stack.","action":"Read the first error in the stack, then go to the unit and line named by ORA-06512. In handlers log DBMS_UTILITY.FORMAT_ERROR_BACKTRACE to keep this information when re-raising."},{"code":"ORA-06550","title":"Line N, column M: PL/SQL compilation error","cause":"An anonymous block or dynamic PL/SQL failed to compile; the PLS- error that follows gives the reason and position.","action":"Read the PLS- error after it (for example PLS-00201 or PLS-00103) and fix the code at the reported line and column of the block."},{"code":"ORA-12899","title":"Value too large for column","cause":"A string is longer than the column size; the message shows the actual and maximum length. With multi-byte character sets (AL32UTF8) a VARCHAR2(10 BYTE) column may hold fewer than 10 characters.","action":"Widen the column or define it with CHAR semantics (VARCHAR2(10 CHAR)), or truncate/validate the input (SUBSTRB for byte limits)."},{"code":"ORA-12154","title":"TNS: could not resolve the connect identifier specified","cause":"The client could not translate the alias in the connect string into an address: missing or wrong entry in tnsnames.ora, the client reads a different TNS_ADMIN, or a typo.","action":"Use EZConnect (host:port/service_name) to skip tnsnames.ora, or check TNS_ADMIN and the alias. JDBC thin URLs use jdbc:oracle:thin:@//host:port/service."},{"code":"ORA-12541","title":"TNS: no listener","cause":"Nothing is listening on the host and port in the connect descriptor: listener is down, wrong port, or a firewall/container port mapping issue.","action":"Start the listener (lsnrctl start), check the port (default 1521) and host, and test with tnsping or a socket check from the client machine."},{"code":"ORA-01555","title":"Snapshot too old","cause":"A long-running query needed an old version of a block from undo to stay read-consistent, but that undo had already been overwritten. Frequent with fetch-across-commit (committing inside a cursor loop over the same table).","action":"Do not commit inside cursor loops, make the query faster, and size undo/UNDO_RETENTION for the longest query. Process data in set-based statements instead of row by row."},{"code":"ORA-04068","title":"Existing state of packages has been discarded","cause":"A package with global (package-level) variables was recompiled while your session was using it, so the session's copy of the package state was thrown away. Often followed by ORA-04061/ORA-04065.","action":"Re-run the call (the second call usually succeeds). To avoid it, keep package state out of frequently deployed packages, move it to a separate state package, or mark stateless packages with PRAGMA SERIALLY_REUSABLE; use Edition-Based Redefinition for zero-downtime deploys."},{"code":"ORA-00018","title":"Maximum number of sessions exceeded","cause":"The instance reached the SESSIONS parameter limit.","action":"Find idle or leaked sessions in v$session (connection pools that never release), fix the leak, or raise SESSIONS (needs a restart)."},{"code":"ORA-00020","title":"Maximum number of processes exceeded","cause":"The instance reached the PROCESSES limit; new dedicated-server connections are refused.","action":"Check connection pool sizes and leaked connections; raise PROCESSES (restart needed) or use shared server / DRCP for many short connections."},{"code":"ORA-00028","title":"Your session has been killed","cause":"A DBA or a resource manager rule killed the session (ALTER SYSTEM KILL SESSION). Its open transaction was rolled back.","action":"Reconnect. Applications using pools should validate connections on borrow. Ask the DBA why it was killed if it repeats (idle time, runaway query rule)."},{"code":"ORA-00031","title":"Session marked for kill","cause":"ALTER SYSTEM KILL SESSION could not end the session immediately (it is rolling back or waiting on an external call), so it was only marked.","action":"Wait for the rollback to finish (v$transaction used_ublk decreases) or use KILL SESSION ... IMMEDIATE / DISCONNECT SESSION ... IMMEDIATE."},{"code":"ORA-00257","title":"Archiver error. Connect internal only, until freed","cause":"The archiver cannot write archived redo logs, usually because the archive destination or the Fast Recovery Area is full; DML stops.","action":"Back up and delete archived logs with RMAN (not with OS commands), or raise DB_RECOVERY_FILE_DEST_SIZE. Check v$recovery_area_usage."},{"code":"ORA-00600","title":"Internal error code","cause":"An internal Oracle error (a bug or corruption). The first argument in brackets identifies the code path.","action":"Look up the first argument in My Oracle Support (ORA-600 lookup tool), check the incident trace in the ADR, and apply the recommended patch or workaround. Re-running the same statement often reproduces it, so look for a rewrite while waiting for a fix."},{"code":"ORA-00900","title":"Invalid SQL statement","cause":"The text sent is not a SQL statement Oracle recognises, for example a SQL*Plus command (DESC, SET, SPOOL, EXEC) sent through JDBC or EXECUTE IMMEDIATE.","action":"Run client commands only in SQL*Plus/SQLcl; in code use a PL/SQL call BEGIN proc; END; instead of EXEC proc."},{"code":"ORA-00902","title":"Invalid datatype","cause":"A column or CAST uses a type name Oracle does not know (BOOLEAN in tables before 23ai, TEXT, DATETIME, INT UNSIGNED...).","action":"Use Oracle types: VARCHAR2, NUMBER, DATE, TIMESTAMP, CLOB, BLOB; NUMBER(1) or CHAR(1) for flags before 23ai."},{"code":"ORA-00903","title":"Invalid table name","cause":"The table name is not a valid identifier (reserved word, starts with a digit, special characters, empty).","action":"Use a valid identifier or quote it (not recommended). Check dynamic SQL where the name comes from a variable."},{"code":"ORA-00905","title":"Missing keyword","cause":"A required keyword is missing in the clause, for example CASE without THEN/END, INTO missing in MERGE, or ON missing in a join.","action":"Compare the clause with the syntax diagram; check CASE ... WHEN ... THEN ... END and MERGE INTO ... USING ... ON (...) WHEN MATCHED THEN UPDATE SET."},{"code":"ORA-00906","title":"Missing left parenthesis","cause":"An opening parenthesis is expected, typically after IN, after VALUES, or around a column list in CREATE TABLE/INDEX.","action":"Add the missing \"(\" and check that IN lists and VALUES lists are enclosed."},{"code":"ORA-00908","title":"Missing NULL keyword","cause":"IS or IS NOT is not followed by NULL (for example WHERE x IS '').","action":"Write IS NULL / IS NOT NULL."},{"code":"ORA-00910","title":"Specified length too long for its datatype","cause":"A size above the type's maximum, for example VARCHAR2(5000) when MAX_STRING_SIZE = STANDARD (limit 4000 bytes in SQL).","action":"Use a CLOB, reduce the size, or (if the database uses MAX_STRING_SIZE = EXTENDED) up to 32767 bytes."},{"code":"ORA-00921","title":"Unexpected end of SQL command","cause":"The statement stops before it is complete, for example a dangling AND, an unfinished IN list, or dynamic SQL cut by a variable that was empty.","action":"Print the final SQL text of dynamic statements and check the end of it."},{"code":"ORA-00922","title":"Missing or invalid option","cause":"An option in CREATE/ALTER is wrong or misplaced, for example a semicolon inside the statement, a wrong storage clause, or a password with special characters not in double quotes.","action":"Check the option syntax for your version; quote passwords with double quotes in CREATE/ALTER USER."},{"code":"ORA-00925","title":"Missing INTO keyword","cause":"INSERT is not followed by INTO.","action":"Write INSERT INTO table ..."},{"code":"ORA-00926","title":"Missing VALUES keyword","cause":"INSERT INTO t (cols) is followed by neither VALUES nor a SELECT.","action":"Add VALUES (...) or a subquery."},{"code":"ORA-00928","title":"Missing SELECT keyword","cause":"A subquery or CREATE VIEW ... AS / INSERT ... with column list is not followed by SELECT where one is required (often a WITH clause placed wrongly).","action":"Check that the WITH clause sits directly before the SELECT it belongs to, and that CREATE VIEW ... AS and INSERT INTO t (cols) are followed by a query."},{"code":"ORA-00934","title":"Group function is not allowed here","cause":"An aggregate (SUM, COUNT...) is used in WHERE or in GROUP BY.","action":"Filter on aggregates with HAVING, or compute the aggregate in a subquery / analytic function and filter in an outer query."},{"code":"ORA-00935","title":"Group function is nested too deeply","cause":"More than two levels of nested aggregates, e.g. MAX(SUM(COUNT(x))).","action":"Compute inner levels in an inline view."},{"code":"ORA-00938","title":"Not enough arguments for function","cause":"A function was called with fewer arguments than required (e.g. NVL(x), SUBSTR(s)).","action":"Check the function signature and add the missing arguments."},{"code":"ORA-00939","title":"Too many arguments for function","cause":"A function was called with more arguments than it accepts (e.g. NVL with 3 arguments).","action":"Use the right function (COALESCE accepts many arguments, NVL only two) or remove the extra arguments."},{"code":"ORA-00946","title":"Missing TO keyword","cause":"GRANT ... or RENAME ... is missing TO.","action":"Write GRANT priv ON obj TO user / RENAME a TO b."},{"code":"ORA-00949","title":"Illegal reference to remote database","cause":"A database link was used where it is not allowed, for example in a constraint, an index definition or a DEFAULT.","action":"Copy the data locally (materialized view) or move the logic out of the DDL."},{"code":"ORA-00957","title":"Duplicate column name","cause":"The same column name appears twice in a CREATE TABLE, INSERT column list or view column list.","action":"Remove or rename the duplicate; give unique aliases to expressions in CREATE TABLE AS SELECT / CREATE VIEW."},{"code":"ORA-00960","title":"Ambiguous column naming in select list","cause":"An ORDER BY refers to a name that matches more than one SELECT list item.","action":"Use unique aliases in the SELECT list or order by position/qualified name."},{"code":"ORA-00971","title":"Missing SET keyword","cause":"UPDATE is not followed by SET.","action":"Write UPDATE table SET col = value ..."},{"code":"ORA-00972","title":"Identifier is too long","cause":"An identifier is longer than allowed: 30 bytes before 12.2, 128 bytes from 12.2 (with COMPATIBLE >= 12.2).","action":"Shorten the name, or check the COMPATIBLE parameter of the database."},{"code":"ORA-00980","title":"Synonym translation is no longer valid","cause":"The synonym points to an object that was dropped or renamed, or to a database link that no longer works.","action":"Recreate the synonym or the target object; list broken ones by joining ALL_SYNONYMS with ALL_OBJECTS."},{"code":"ORA-00984","title":"Column not allowed here","cause":"A column name appears where only a value or expression without columns is allowed, typically in INSERT ... VALUES (an unquoted string literal looks like a column name).","action":"Put string literals in single quotes; use INSERT ... SELECT when you need values from other columns."},{"code":"ORA-00997","title":"Illegal use of LONG datatype","cause":"A LONG column was used in a place that does not accept it (WHERE, functions, INSERT ... SELECT, CTAS, GROUP BY).","action":"Convert the column to CLOB (ALTER TABLE ... MODIFY col CLOB) or use TO_LOB in INSERT ... SELECT."},{"code":"ORA-01002","title":"Fetch out of sequence","cause":"A fetch was done on a cursor that is already exhausted or no longer valid, often after a COMMIT on a SELECT ... FOR UPDATE cursor, or JDBC autocommit with FOR UPDATE.","action":"Do not commit while looping over a FOR UPDATE cursor; disable autocommit for such cursors; stop fetching after NOTFOUND."},{"code":"ORA-01008","title":"Not all variables bound","cause":"The statement has bind placeholders (:name or ?) that did not receive a value, or a colon inside a string literal/comment was treated as a bind.","action":"Bind every placeholder (in EXECUTE IMMEDIATE ... USING give one value per placeholder occurrence in SQL), and check literals like ':00' in dynamic SQL."},{"code":"ORA-01012","title":"Not logged on","cause":"The session no longer exists (it was killed, timed out, or the connection was lost) but the client used it.","action":"Reconnect; validate pooled connections before use."},{"code":"ORA-01031","title":"Insufficient privileges","cause":"The user lacks a system or object privilege for the operation. In definer-rights PL/SQL, privileges from roles are not active, so a CREATE TABLE via EXECUTE IMMEDIATE needs a direct grant.","action":"Grant the privilege directly to the user (GRANT CREATE TABLE TO app) or use invoker rights (AUTHID CURRENT_USER) where appropriate."},{"code":"ORA-01033","title":"ORACLE initialization or shutdown in progress","cause":"The instance is starting or stopping, or the PDB is mounted but not open.","action":"Wait, or open the PDB (ALTER PLUGGABLE DATABASE name OPEN) and save its state."},{"code":"ORA-01034","title":"ORACLE not available","cause":"The instance is not started (or ORACLE_SID/ORACLE_HOME point to another instance).","action":"Start the instance, check ORACLE_SID and ORACLE_HOME, and look at the alert log for startup errors."},{"code":"ORA-01039","title":"Insufficient privileges on underlying objects of the view","cause":"EXPLAIN PLAN or a grant on a view failed because you lack privileges on the base tables.","action":"Get SELECT on the base tables, or have the view owner grant WITH GRANT OPTION."},{"code":"ORA-01045","title":"User lacks CREATE SESSION privilege; logon denied","cause":"The account exists but cannot connect.","action":"GRANT CREATE SESSION TO user (directly or through a role)."},{"code":"ORA-01089","title":"Immediate shutdown or close in progress","cause":"The database is closing; new operations are refused.","action":"Wait for the instance to be restarted."},{"code":"ORA-01157","title":"Cannot identify/lock data file","cause":"A data file listed in the control file is missing or cannot be opened (moved, deleted, permissions).","action":"Restore the file or correct its path; if it belongs to a temporary tablespace, add a new tempfile and drop the missing one."},{"code":"ORA-01401","title":"Inserted value too large for column","cause":"Older form of ORA-12899: the value is longer than the column.","action":"Widen the column or validate the input length."},{"code":"ORA-01408","title":"Such column list already indexed","cause":"An index with exactly the same column list already exists.","action":"Use the existing index, or (12c+) create the new one INVISIBLE or with a different type/uniqueness."},{"code":"ORA-01410","title":"Invalid ROWID","cause":"A ROWID value is malformed or points to a row that moved (partition move, table shrink, IOT).","action":"Do not store ROWIDs long term; use primary keys. Re-read the row by key."},{"code":"ORA-01417","title":"A table may be outer joined to at most one other table","cause":"With the old (+) syntax a table cannot be outer joined to two others.","action":"Rewrite with ANSI LEFT JOIN, which supports this."},{"code":"ORA-01418","title":"Specified index does not exist","cause":"ALTER/DROP INDEX names an index that is missing or in another schema.","action":"Check ALL_INDEXES and qualify with the owner."},{"code":"ORA-01430","title":"Column being added already exists in table","cause":"ALTER TABLE ADD uses an existing column name.","action":"Skip the step in re-runnable scripts (check ALL_TAB_COLUMNS) or use MODIFY."},{"code":"ORA-01436","title":"CONNECT BY loop in user data","cause":"A hierarchical query found a cycle (a row is its own ancestor).","action":"Use CONNECT BY NOCYCLE and CONNECT_BY_ISCYCLE to find the loop, then fix the data. Recursive WITH has a CYCLE clause."},{"code":"ORA-01439","title":"Column to be modified must be empty to change datatype","cause":"ALTER TABLE MODIFY tried to change the type of a column that has data.","action":"Add a new column, copy with conversion, drop the old one and rename; or use DBMS_REDEFINITION online."},{"code":"ORA-01440","title":"Column to be modified must be empty to decrease precision or scale","cause":"Reducing NUMBER precision/scale is only allowed on empty columns.","action":"Use the add-copy-drop-rename approach."},{"code":"ORA-01441","title":"Cannot decrease column length because some value is too big","cause":"Some existing values are longer than the new size.","action":"Find them with WHERE LENGTH(col) > n, fix them, then shrink the column."},{"code":"ORA-01445","title":"Cannot select ROWID from, or sample, a join view without a key-preserved table","cause":"A query (or an updatable-view operation) needs the ROWID of a join view, but no table is key-preserved.","action":"Join on primary/unique keys so one table is key-preserved, or select from the base table."},{"code":"ORA-01450","title":"Maximum key length exceeded","cause":"The total size of the indexed columns exceeds the limit for the block size.","action":"Index fewer/shorter columns, use a function-based index on a hash or SUBSTR, or a bigger block size tablespace."},{"code":"ORA-01451","title":"Column to be modified to NULL cannot be modified to NULL","cause":"The column is already nullable.","action":"Skip this step in the script."},{"code":"ORA-01452","title":"Cannot CREATE UNIQUE INDEX; duplicate keys found","cause":"Existing data violates the uniqueness you want to enforce.","action":"Find duplicates with GROUP BY ... HAVING COUNT(*) > 1 and clean them, or use EXCEPTIONS INTO with a constraint."},{"code":"ORA-01453","title":"SET TRANSACTION must be first statement of transaction","cause":"SET TRANSACTION was issued after DML in the current transaction.","action":"COMMIT or ROLLBACK first, then SET TRANSACTION."},{"code":"ORA-01456","title":"May not perform insert/delete/update operation inside a READ ONLY transaction","cause":"DML in a transaction started with SET TRANSACTION READ ONLY (or on a read-only standby).","action":"End the read-only transaction first, or connect to the primary."},{"code":"ORA-01468","title":"A predicate may reference only one outer-joined table","cause":"Old (+) syntax limitation.","action":"Rewrite with ANSI OUTER JOIN."},{"code":"ORA-01471","title":"Cannot create a synonym with same name as object","cause":"The synonym name equals the object name in the same schema.","action":"Use a different name or create the synonym in another schema / as PUBLIC."},{"code":"ORA-01481","title":"Invalid number format model","cause":"TO_CHAR/TO_NUMBER received an invalid number mask.","action":"Check the mask elements (9, 0, D, G, FM, L...)."},{"code":"ORA-01489","title":"Result of string concatenation is too long","cause":"A concatenation in SQL exceeds 4000 bytes (VARCHAR2 limit with STANDARD string size), often with LISTAGG or ||.","action":"Use LISTAGG ... ON OVERFLOW TRUNCATE (12.2+), XMLAGG/JSON_ARRAYAGG with CLOB, or TO_CLOB on the first operand."},{"code":"ORA-01502","title":"Index or partition of such index is in unusable state","cause":"DML or a query needs an index marked UNUSABLE (after a partition maintenance, direct-path load or ALTER TABLE MOVE).","action":"ALTER INDEX name REBUILD (ONLINE); use UPDATE INDEXES in partition maintenance."},{"code":"ORA-01536","title":"Space quota exceeded for tablespace","cause":"The user has a quota limit on the tablespace and reached it.","action":"ALTER USER name QUOTA 500M (or UNLIMITED) ON tablespace."},{"code":"ORA-01578","title":"ORACLE data block corrupted","cause":"A block failed its checks when read.","action":"Run RMAN VALIDATE, restore/recover the block (RMAN RECOVER BLOCK), and check storage. Involve the DBA."},{"code":"ORA-01652","title":"Unable to extend temp segment","cause":"The temporary tablespace is full: large sorts, hash joins or global temporary tables.","action":"Look for a bad plan (cartesian join, missing join condition) first; then add tempfiles or enable autoextend."},{"code":"ORA-01653","title":"Unable to extend table in tablespace","cause":"The tablespace has no free space for a new extent of the table.","action":"Add a datafile or enable autoextend; purge the recycle bin; check DBA_FREE_SPACE."},{"code":"ORA-01654","title":"Unable to extend index in tablespace","cause":"Same as ORA-01653 for an index.","action":"Add space to the tablespace or rebuild the index elsewhere."},{"code":"ORA-01720","title":"Grant option does not exist","cause":"You granted access on a view that uses another schema's objects without having those privileges WITH GRANT OPTION.","action":"Ask the owner of the base objects to grant them to you WITH GRANT OPTION."},{"code":"ORA-01727","title":"Numeric precision specifier is out of range (1 to 38)","cause":"NUMBER(p) with p outside 1..38.","action":"Use a precision between 1 and 38, or NUMBER without precision."},{"code":"ORA-01732","title":"Data manipulation operation not legal on this view","cause":"The view is not updatable (DISTINCT, GROUP BY, aggregates, set operators...).","action":"Update the base table, or add an INSTEAD OF trigger to the view."},{"code":"ORA-01735","title":"Invalid ALTER TABLE option","cause":"The ALTER TABLE syntax is wrong, often ADD COLUMN (Oracle uses ADD) or MODIFY with wrong parentheses.","action":"Write ALTER TABLE t ADD (col type) / MODIFY (col type)."},{"code":"ORA-01741","title":"Illegal zero-length identifier","cause":"Empty double quotes \"\" were used as an identifier, often from a generated script.","action":"Remove the empty quoted name or give it a value."},{"code":"ORA-01747","title":"Invalid user.table.column, table.column, or column specification","cause":"A column name is a reserved word or is malformed (e.g. a column called DATE or COMMENT in an UPDATE SET).","action":"Rename the column or quote it (\"DATE\")."},{"code":"ORA-01756","title":"Quoted string not properly terminated","cause":"A string literal is missing its closing quote, often because of an apostrophe inside the text.","action":"Double apostrophes inside literals ('O''Brien') or use q-quotes: q'[O'Brien]'."},{"code":"ORA-01779","title":"Cannot modify a column which maps to a non key-preserved table","cause":"UPDATE on a join (inline view) where the updated table is not key-preserved.","action":"Make the join use a unique key of the other table, or use MERGE."},{"code":"ORA-01790","title":"Expression must have same datatype as corresponding expression","cause":"Columns of UNION/INTERSECT/MINUS branches have different types at the same position.","action":"Convert explicitly (TO_CHAR, CAST) so each position has the same type; use CAST(NULL AS type) for empty columns."},{"code":"ORA-01791","title":"Not a SELECTed expression","cause":"With SELECT DISTINCT (or a set operator), ORDER BY uses an expression that is not in the select list.","action":"Add the expression to the SELECT list or order in an outer query."},{"code":"ORA-01795","title":"Maximum number of expressions in a list is 1000","cause":"An IN list has more than 1000 literals.","action":"Load the values into a global temporary table or collection and join / use IN (SELECT ...); or use tuples IN ((1,0),(2,0)) as a workaround."},{"code":"ORA-01799","title":"A column may not be outer-joined to a subquery","cause":"Old (+) syntax with a subquery on the outer-joined side.","action":"Rewrite with ANSI LEFT JOIN."},{"code":"ORA-01821","title":"Date format not recognized","cause":"The date mask contains an element Oracle does not know (e.g. yyyy-mm-dd hh:mm:ss uses MM for minutes; must be MI).","action":"Use valid elements: MI for minutes, HH24 for 24h hours, FF for fractions in timestamps."},{"code":"ORA-01839","title":"Date not valid for month specified","cause":"The day does not exist in that month (e.g. 31-04 or 29-02 in a non-leap year).","action":"Validate input, or use ADD_MONTHS/LAST_DAY for date arithmetic."},{"code":"ORA-01840","title":"Input value not long enough for date format","cause":"The input string is shorter than the mask requires.","action":"Make the mask match the data or use FX/FM modifiers consciously."},{"code":"ORA-01841","title":"(Full) year must be between -4713 and +9999, and not be 0","cause":"The year part is out of range, often from wrong masks (YY vs YYYY) or a number passed as date.","action":"Check the mask and the input; avoid implicit date conversion."},{"code":"ORA-01847","title":"Day of month must be between 1 and last day of month","cause":"Day value out of range, often from swapped day/month.","action":"Use the correct mask (DD/MM vs MM/DD)."},{"code":"ORA-01849","title":"Hour must be between 1 and 12","cause":"A 24-hour value was parsed with HH or HH12.","action":"Use HH24 in the mask."},{"code":"ORA-01850","title":"Hour must be between 0 and 23","cause":"The hour part is out of range.","action":"Validate the input and mask."},{"code":"ORA-01851","title":"Minutes must be between 0 and 59","cause":"The minutes part is out of range, often because MM (month) and MI (minutes) are mixed up.","action":"Use MI for minutes."},{"code":"ORA-01858","title":"A non-numeric character was found where a numeric was expected","cause":"The input has letters where the mask expects digits, or the mask is wrong (DD-MON-YYYY vs DD-MM-YYYY).","action":"Match the mask to the data; check NLS settings when no mask is given."},{"code":"ORA-01873","title":"The leading precision of the interval is too small","cause":"An INTERVAL value does not fit its leading field precision (default 2 digits, e.g. INTERVAL '100' DAY).","action":"Declare more precision: INTERVAL '100' DAY(3), or NUMTODSINTERVAL."},{"code":"ORA-01882","title":"Timezone region not found","cause":"The time zone name is unknown to the server, or the client (JDBC driver) sends a region the database time zone file does not know.","action":"Update the time zone file (DST patch), set the JVM -Duser.timezone to a known region, or use an offset like +02:00."},{"code":"ORA-01918","title":"User does not exist","cause":"The user named in the statement does not exist (or not in this PDB).","action":"Check DBA_USERS/ALL_USERS and the container you are connected to."},{"code":"ORA-01920","title":"User name conflicts with another user or role name","cause":"CREATE USER/ROLE with a name already used by a user or role.","action":"Choose another name."},{"code":"ORA-01940","title":"Cannot drop a user that is currently connected","cause":"DROP USER while the user has sessions.","action":"Kill the user's sessions (v$session where username = ...) and drop again; lock the account first to stop new logins."},{"code":"ORA-01950","title":"No privileges on tablespace","cause":"The user has no quota on the tablespace where it tries to create a segment.","action":"ALTER USER name QUOTA UNLIMITED ON tablespace (or a size)."},{"code":"ORA-02049","title":"Timeout: distributed transaction waiting for lock","cause":"A distributed transaction (database link) waited longer than DISTRIBUTED_LOCK_TIMEOUT for a lock.","action":"Find the blocker on the remote side; keep distributed transactions short."},{"code":"ORA-02063","title":"Preceding line from (dblink)","cause":"Not an error by itself: the error above happened in the remote database reached through the named database link.","action":"Read the error just above it and investigate on the remote database."},{"code":"ORA-02149","title":"Specified partition does not exist","cause":"The partition name in the statement is wrong.","action":"Check ALL_TAB_PARTITIONS or use PARTITION FOR (value)."},{"code":"ORA-02260","title":"Table can have only one primary key","cause":"A second PRIMARY KEY was defined.","action":"Use a UNIQUE constraint for the other key."},{"code":"ORA-02264","title":"Name already used by an existing constraint","cause":"Constraint names are unique per schema.","action":"Use another name."},{"code":"ORA-02266","title":"Unique/primary keys in table referenced by enabled foreign keys","cause":"TRUNCATE on a parent table with enabled foreign keys pointing to it.","action":"Disable the child foreign keys, truncate, then enable them; or DELETE; or (12c+) TRUNCATE ... CASCADE with ON DELETE CASCADE keys."},{"code":"ORA-02270","title":"No matching unique or primary key for this column-list","cause":"A foreign key references columns that are not a primary key or unique constraint in the parent table.","action":"Add a PK/UNIQUE constraint on the referenced columns or reference the right columns."},{"code":"ORA-02275","title":"Such a referential constraint already exists in the table","cause":"An identical foreign key already exists.","action":"Skip the step."},{"code":"ORA-02287","title":"Sequence number not allowed here","cause":"NEXTVAL/CURRVAL used where it is forbidden: with DISTINCT, GROUP BY, ORDER BY, UNION, in a subquery or view.","action":"Generate the value in an outer query or use an identity column / DEFAULT seq.NEXTVAL."},{"code":"ORA-02289","title":"Sequence does not exist","cause":"The sequence is missing, in another schema, or you lack SELECT on it.","action":"Check ALL_SEQUENCES, prefix the owner, grant SELECT on the sequence."},{"code":"ORA-02290","title":"Check constraint violated","cause":"The value does not satisfy a CHECK constraint (named in the message).","action":"Look up the condition in ALL_CONSTRAINTS.search_condition and fix the value."},{"code":"ORA-02296","title":"Cannot enable (constraint) - null values found","cause":"Making a column NOT NULL failed because it contains NULLs.","action":"Update the NULLs first, or use ENABLE NOVALIDATE."},{"code":"ORA-02298","title":"Cannot validate - parent keys not found","cause":"Enabling a foreign key failed because orphan rows exist.","action":"Find orphans with NOT EXISTS against the parent, fix them, or use ENABLE NOVALIDATE."},{"code":"ORA-02303","title":"Cannot drop or replace a type with type or table dependents","cause":"An object type is used by tables or other types.","action":"Use ALTER TYPE ... CASCADE or CREATE OR REPLACE TYPE ... FORCE (only if no table data depends on it)."},{"code":"ORA-02391","title":"Exceeded simultaneous SESSIONS_PER_USER limit","cause":"The user's profile limits the number of sessions.","action":"Close idle sessions or raise the profile limit."},{"code":"ORA-02396","title":"Exceeded maximum idle time, please connect again","cause":"The profile's IDLE_TIME expired.","action":"Reconnect; configure pools to validate/refresh connections."},{"code":"ORA-02429","title":"Cannot drop index used for enforcement of unique/primary key","cause":"The index backs a constraint.","action":"Drop or disable the constraint (ALTER TABLE ... DROP CONSTRAINT ... DROP INDEX)."},{"code":"ORA-02437","title":"Cannot validate (primary key) - primary key violated","cause":"Existing data has duplicates or NULLs in the key.","action":"Clean the data first."},{"code":"ORA-02449","title":"Unique/primary keys in table referenced by foreign keys","cause":"DROP TABLE on a parent table.","action":"DROP TABLE ... CASCADE CONSTRAINTS, or drop the child foreign keys first."},{"code":"ORA-03113","title":"End-of-file on communication channel","cause":"The connection to the server process was broken: the server process died (check for ORA-00600/07445 in the alert log), a firewall dropped an idle connection, or the instance went down.","action":"Check the alert log and trace files for the time of the error; for idle drops configure SQLNET.EXPIRE_TIME / keepalive."},{"code":"ORA-03114","title":"Not connected to ORACLE","cause":"The client tried to use a connection that was already lost (usually after ORA-03113).","action":"Reconnect; find out why the first error happened."},{"code":"ORA-03135","title":"Connection lost contact","cause":"The network connection was lost (timeout, firewall, server crash).","action":"Check network/firewall idle timeouts and set SQLNET.EXPIRE_TIME; check the alert log."},{"code":"ORA-04021","title":"Timeout occurred while waiting to lock object","cause":"DDL or compilation could not get a library cache lock, because the object (package, procedure) is in use.","action":"Compile when the code is not running; find sessions using it in v$access / DBA_DDL_LOCKS."},{"code":"ORA-04030","title":"Out of process memory when trying to allocate","cause":"The server process could not get more PGA memory, often a huge collection in PL/SQL (BULK COLLECT without LIMIT) or OS limits.","action":"Use BULK COLLECT ... LIMIT, free collections, review PGA_AGGREGATE_LIMIT and OS limits."},{"code":"ORA-04031","title":"Unable to allocate bytes of shared memory","cause":"The shared pool (or large/java pool) is fragmented or too small, very often due to SQL without bind variables flooding the library cache.","action":"Use bind variables, size the SGA properly; flushing the shared pool is only a temporary relief."},{"code":"ORA-04043","title":"Object does not exist","cause":"DESCRIBE or another command named an object that is missing.","action":"Check the name, owner and case."},{"code":"ORA-04061","title":"Existing state of (package) has been invalidated","cause":"The package was recompiled; see ORA-04068.","action":"Re-run the call; reduce package state."},{"code":"ORA-04063","title":"(Object) has errors","cause":"The view or stored unit is invalid because of compilation errors.","action":"SELECT * FROM all_errors WHERE name = '<NAME>' and fix them, then recompile."},{"code":"ORA-04065","title":"Not executed, altered or dropped stored procedure","cause":"The unit was changed after the session loaded it; see ORA-04068.","action":"Re-run; avoid deploying during load."},{"code":"ORA-04080","title":"Trigger does not exist","cause":"ALTER/DROP TRIGGER names a missing trigger.","action":"Check ALL_TRIGGERS."},{"code":"ORA-04082","title":"NEW or OLD references not allowed in table level triggers","cause":":NEW/:OLD used in a statement-level trigger.","action":"Add FOR EACH ROW or use a compound trigger."},{"code":"ORA-04084","title":"Cannot change NEW values for this trigger type","cause":":NEW assigned in an AFTER row trigger (or a statement trigger).","action":"Assign :NEW values in a BEFORE EACH ROW trigger."},{"code":"ORA-04088","title":"Error during execution of trigger","cause":"A trigger raised an error; the error above it in the stack is the real cause.","action":"Read the preceding error and the trigger named in this message."},{"code":"ORA-04092","title":"Cannot COMMIT or ROLLBACK in a trigger","cause":"A trigger (or code called by it) issued COMMIT/ROLLBACK.","action":"Remove it; let the caller control the transaction. Use an autonomous transaction only for logging."},{"code":"ORA-04098","title":"Trigger is invalid and failed re-validation","cause":"The trigger has compilation errors, so any DML on the table fails.","action":"Check ALL_ERRORS for the trigger, fix and recompile, or disable it temporarily."},{"code":"ORA-06501","title":"PL/SQL: program error","cause":"An internal PL/SQL error (PROGRAM_ERROR).","action":"Check for known bugs for your version; simplify the code path."},{"code":"ORA-06503","title":"PL/SQL: Function returned without value","cause":"A function reached its END without executing RETURN, often in an exception handler.","action":"Make every path end with RETURN, including handlers."},{"code":"ORA-06504","title":"PL/SQL: Return types of Result Set variables or query do not match","cause":"A cursor variable is opened for a query whose columns do not match the declared record type.","action":"Match the SELECT list with the record/strong REF CURSOR type."},{"code":"ORA-06511","title":"PL/SQL: cursor already open","cause":"OPEN on a cursor that is already open.","action":"Close it first, or check %ISOPEN."},{"code":"ORA-06519","title":"Active autonomous transaction detected and rolled back","cause":"An autonomous transaction routine ended without COMMIT/ROLLBACK after doing DML.","action":"Add COMMIT (or ROLLBACK) before every exit of the autonomous routine."},{"code":"ORA-06530","title":"Reference to uninitialized composite","cause":"An attribute of an object type instance was set while the object itself is NULL.","action":"Initialise with the constructor: v := my_type(NULL, NULL);"},{"code":"ORA-06531","title":"Reference to uninitialized collection","cause":"A nested table or varray was used before being initialised.","action":"Initialise with the constructor (v := t_tab()) or BULK COLLECT into it; associative arrays need no initialisation."},{"code":"ORA-06532","title":"Subscript outside of limit","cause":"A varray index exceeds its declared maximum size, or an index is negative/zero.","action":"Check the index and the varray limit."},{"code":"ORA-06533","title":"Subscript beyond count","cause":"An index of a nested table/varray is greater than COUNT (EXTEND was not called).","action":"Call EXTEND before assigning, or loop 1..COUNT."},{"code":"ORA-06535","title":"Statement string in EXECUTE IMMEDIATE is NULL or 0 length","cause":"The dynamic SQL string is empty.","action":"Check how the string is built; log it before executing."},{"code":"ORA-06576","title":"Not a valid function or procedure name","cause":"CALL/EXEC with something that is not a callable name, or a function called with CALL without INTO.","action":"Use CALL f() INTO :x for functions, or check the name."},{"code":"ORA-08002","title":"Sequence CURRVAL is not yet defined in this session","cause":"CURRVAL was read before NEXTVAL in the same session.","action":"Call NEXTVAL first; use RETURNING INTO to get generated keys."},{"code":"ORA-08004","title":"Sequence NEXTVAL exceeds MAXVALUE and cannot be instantiated","cause":"The sequence reached MAXVALUE and is NOCYCLE.","action":"ALTER SEQUENCE ... MAXVALUE higher (or NOMAXVALUE)."},{"code":"ORA-08177","title":"Can't serialize access for this transaction","cause":"In SERIALIZABLE isolation a row changed by another committed transaction after yours began was updated.","action":"Retry the transaction, or use READ COMMITTED with explicit locking."},{"code":"ORA-12170","title":"TNS: Connect timeout occurred","cause":"The client did not get a response from the host within the timeout: firewall, wrong host/port, network routing.","action":"Check connectivity (telnet/nc host 1521), firewalls and the connect timeout settings."},{"code":"ORA-12505","title":"TNS: listener does not currently know of SID","cause":"The connect descriptor uses a SID the listener does not know (often the service name was given as SID).","action":"Use the service name syntax (host:port/service), check lsnrctl status."},{"code":"ORA-12514","title":"TNS: listener does not currently know of service requested","cause":"The listener is reachable but no database has registered that service name (wrong name, PDB closed, instance down).","action":"Check lsnrctl status / v$services, open the PDB, use the exact service name."},{"code":"ORA-12516","title":"TNS: listener could not find available handler with matching protocol stack","cause":"The database reached PROCESSES/SESSIONS, or the service handler is blocked.","action":"Check PROCESSES usage and leaked connections; see ORA-00020."},{"code":"ORA-12519","title":"TNS: no appropriate service handler found","cause":"Same family as ORA-12516: the instance is out of processes or blocked.","action":"Check PROCESSES and connection pool sizes."},{"code":"ORA-12528","title":"TNS: listener: all appropriate instances are blocking new connections","cause":"The instance is mounted/restricted or starting.","action":"Wait for the database to open or check restricted mode."},{"code":"ORA-12537","title":"TNS: connection closed","cause":"The connection was closed while being established (server process could not start, invited nodes restrictions, limits).","action":"Check the listener log and sqlnet.ora (tcp.validnode_checking), and OS process limits."},{"code":"ORA-12543","title":"TNS: destination host unreachable","cause":"The host cannot be reached on the network.","action":"Check the host name, DNS, VPN and routing."},{"code":"ORA-12545","title":"Connect failed because target host or object does not exist","cause":"The host name in the connect descriptor cannot be resolved or is wrong.","action":"Fix the host name or use the IP; check DNS/hosts file."},{"code":"ORA-12560","title":"TNS: protocol adapter error","cause":"Usually on Windows: the Oracle service is not running or ORACLE_SID is wrong for a local connection.","action":"Start the OracleService<SID> Windows service, set ORACLE_SID, or connect through the listener."},{"code":"ORA-12801","title":"Error signaled in parallel query server","cause":"A parallel execution slave hit an error; the real error follows in the stack.","action":"Read the next error (for example ORA-01652 or ORA-01722)."},{"code":"ORA-12838","title":"Cannot read/modify an object after modifying it in parallel","cause":"After a direct-path/parallel INSERT (APPEND) the same transaction tried to access the table again.","action":"COMMIT after the direct-path load before reading or changing the table."},{"code":"ORA-14400","title":"Inserted partition key does not map to any partition","cause":"The partition key value is outside every defined range/list partition.","action":"Add a partition, a MAXVALUE/DEFAULT partition, or use interval partitioning."},{"code":"ORA-14402","title":"Updating partition key column would cause a partition change","cause":"An UPDATE changes the partition key so the row would move to another partition.","action":"ALTER TABLE ... ENABLE ROW MOVEMENT."},{"code":"ORA-14450","title":"Attempt to access a transactional temp table already in use","cause":"DDL on a global temporary table while a session has data in it (ON COMMIT PRESERVE ROWS).","action":"End the sessions using it or TRUNCATE it in those sessions first."},{"code":"ORA-14551","title":"Cannot perform a DML operation inside a query","cause":"A function called from a SELECT does DML.","action":"Do not call DML functions from SQL; call them from PL/SQL. An autonomous transaction is possible but usually a design smell."},{"code":"ORA-14552","title":"Cannot perform a DDL, commit or rollback inside a query or DML","cause":"A function called from SQL issued COMMIT/ROLLBACK/DDL.","action":"Move the transaction control out of functions used in SQL."},{"code":"ORA-19011","title":"Character string buffer too small","cause":"An XML function result does not fit VARCHAR2 (getStringVal on large XML).","action":"Use getClobVal / XMLSERIALIZE(... AS CLOB)."},{"code":"ORA-20000","title":"User-defined application error (ORA-20000..-20999)","cause":"Raised by application code with RAISE_APPLICATION_ERROR; the text is written by the developer, not by Oracle.","action":"Read the message text and the ORA-06512 lines below it to find the raising code."},{"code":"ORA-22813","title":"Operand value exceeds system limits","cause":"A collection/object operation exceeded an internal limit, often a large collection in SQL (TABLE(), MULTISET) or GROUP BY on a big object.","action":"Reduce collection size, use temporary tables instead of huge collections in SQL."},{"code":"ORA-22835","title":"Buffer too small for CLOB to CHAR or BLOB to RAW conversion","cause":"A CLOB longer than 4000 bytes was converted to VARCHAR2 in SQL (implicitly or with TO_CHAR).","action":"Use DBMS_LOB.SUBSTR(clob, 4000, 1) or keep the value as CLOB."},{"code":"ORA-24247","title":"Network access denied by access control list (ACL)","cause":"UTL_HTTP/UTL_SMTP/UTL_TCP tried to reach a host that is not allowed for the user.","action":"Add an ACE with DBMS_NETWORK_ACL_ADMIN.APPEND_HOST_ACE for the host, port and principal."},{"code":"ORA-24381","title":"Error(s) in array DML","cause":"FORALL ... SAVE EXCEPTIONS found errors in some iterations.","action":"Loop over SQL%BULK_EXCEPTIONS to get each failed index and error code."},{"code":"ORA-28000","title":"The account is locked","cause":"The account was locked by a DBA or after too many failed logins (FAILED_LOGIN_ATTEMPTS).","action":"ALTER USER name ACCOUNT UNLOCK; find the source of wrong passwords (old app config)."},{"code":"ORA-28001","title":"The password has expired","cause":"The profile's PASSWORD_LIFE_TIME passed.","action":"Change the password; for service accounts use a profile with PASSWORD_LIFE_TIME UNLIMITED."},{"code":"ORA-28002","title":"The password will expire within N days","cause":"Warning in the grace period.","action":"Change the password soon."},{"code":"ORA-28040","title":"No matching authentication protocol","cause":"Client and server disagree on the minimum authentication protocol (old client against a new server).","action":"Upgrade the client driver; as a temporary measure adjust SQLNET.ALLOWED_LOGON_VERSION_SERVER on the server."},{"code":"ORA-29273","title":"HTTP request failed","cause":"UTL_HTTP failed; the next error explains why (ACL, wallet/certificate, network).","action":"Read the following error (ORA-24247, ORA-29024 certificate validation...) and configure ACL or wallet."},{"code":"ORA-29280","title":"Invalid directory path","cause":"UTL_FILE got a directory that is not a DIRECTORY object or is not accessible.","action":"Use a DIRECTORY object name (CREATE DIRECTORY) and grant READ/WRITE on it."},{"code":"ORA-29283","title":"Invalid file operation","cause":"UTL_FILE could not open/read/write the file: OS permissions, missing file or path.","action":"Check OS permissions for the oracle user and that the file exists on the database server."},{"code":"ORA-30926","title":"Unable to get a stable set of rows in the source tables","cause":"MERGE matched the same target row with more than one source row.","action":"Make the USING source unique per ON key (deduplicate with ROW_NUMBER or GROUP BY)."},{"code":"ORA-31011","title":"XML parsing failed","cause":"The XML text is not well formed.","action":"Validate the XML (encoding, escaped & and <)."},{"code":"ORA-38104","title":"Columns referenced in the ON Clause cannot be updated","cause":"MERGE ... WHEN MATCHED THEN UPDATE SET changes a column used in ON.","action":"Remove that column from SET, or use a separate UPDATE."},{"code":"ORA-40441","title":"JSON syntax error","cause":"The text passed to a JSON function or IS JSON column is not valid JSON.","action":"Validate the JSON; use the ERROR/NULL ON ERROR clauses to control behaviour."},{"code":"PLS-00049","title":"Bad bind variable","cause":"A :name in PL/SQL is not a valid bind (for example :NEW misspelt in a trigger, or a bind used in stored code).","action":"Check :NEW/:OLD spelling in triggers; in stored code use variables, not binds."},{"code":"PLS-00103","title":"Encountered the symbol X when expecting one of the following","cause":"Syntax error: a missing semicolon, END, THEN, LOOP, or a keyword in the wrong place.","action":"Look at the line before the reported position: a missing \";\" at the end of the previous statement is the most common cause."},{"code":"PLS-00201","title":"Identifier must be declared","cause":"The name is unknown: typo, missing declaration, object in another schema, or a privilege granted only through a role (not visible in stored PL/SQL).","action":"Declare it, qualify with the schema, or grant the privilege directly to the owner of the code."},{"code":"PLS-00221","title":"Is not a procedure or is undefined","cause":"A function was called as a procedure (its return value ignored), or the name is wrong.","action":"Assign the result: x := f(...); or call the procedure that exists."},{"code":"PLS-00222","title":"No function with name exists in this scope","cause":"A procedure or unknown name was used as a function.","action":"Check the name and whether it is a function."},{"code":"PLS-00231","title":"Function may not be used in SQL","cause":"A function used in SQL is private to the package body or has a non-SQL type.","action":"Declare the function in the package specification and use SQL types (12c: or a WITH FUNCTION)."},{"code":"PLS-00302","title":"Component must be declared","cause":"The part after a dot is unknown: package member not in the spec, record field typo, or a schema and a package/object with the same name confuse resolution.","action":"Add the member to the package specification, fix the field name, or rename the colliding object."},{"code":"PLS-00306","title":"Wrong number or types of arguments in call","cause":"The call does not match any overload of the subprogram.","action":"Compare with the declaration; use named notation (p_name => value) to see which argument is wrong."},{"code":"PLS-00307","title":"Too many declarations match this call","cause":"More than one overload fits the call, so the call is ambiguous.","action":"Use named notation or explicit conversions to pick one overload."},{"code":"PLS-00313","title":"Not declared in this scope","cause":"A name was referenced outside the block where it is visible.","action":"Move the declaration or reference it where it is visible."},{"code":"PLS-00320","title":"The declaration of the type of this expression is incomplete or malformed","cause":"A %TYPE/%ROWTYPE refers to something missing (a column that was dropped/renamed, or a table you cannot see).","action":"Fix the referenced table/column or the privilege."},{"code":"PLS-00323","title":"Subprogram is declared in a package specification and must be defined in the package body","cause":"The spec has a procedure/function whose body is missing or has a different signature.","action":"Add the body with exactly the same parameter names, modes and types."},{"code":"PLS-00328","title":"A subprogram body must be defined for the forward declaration","cause":"A forward-declared private subprogram has no body.","action":"Write the body in the same package body or remove the declaration."},{"code":"PLS-00357","title":"Table, view or sequence reference not allowed in this context","cause":"A table or sequence was used in a PL/SQL expression outside SQL (before 11g: seq.NEXTVAL directly in PL/SQL).","action":"Use it inside a SQL statement (SELECT seq.NEXTVAL INTO ...) or upgrade syntax (11g+ allows v := seq.NEXTVAL)."},{"code":"PLS-00363","title":"Expression cannot be used as an assignment target","cause":"Assignment to an IN parameter, a constant, or a function result.","action":"Copy the IN parameter to a local variable, or declare the parameter IN OUT."},{"code":"PLS-00371","title":"At most one declaration for (name) is permitted","cause":"The same name is declared twice in a block.","action":"Remove or rename the duplicate."},{"code":"PLS-00382","title":"Expression is of wrong type","cause":"The expression type does not match the target (e.g. assigning a record to a scalar, BOOLEAN in SQL).","action":"Convert explicitly or use the right variable type."},{"code":"PLS-00386","title":"Type mismatch found between FETCH cursor and INTO variables","cause":"FETCH INTO variables whose types do not match the cursor columns.","action":"Fetch into a record declared as cursor%ROWTYPE."},{"code":"PLS-00394","title":"Wrong number of values in the INTO list of a FETCH statement","cause":"The INTO list has a different number of variables than the cursor columns.","action":"Match the count, or fetch into cursor%ROWTYPE."},{"code":"PLS-00402","title":"Alias required in SELECT list of cursor to avoid duplicate column names","cause":"Two columns of the cursor query have the same name (e.g. ID from two tables).","action":"Give them aliases."},{"code":"PLS-00403","title":"Expression cannot be used as an INTO-target of a SELECT/FETCH statement","cause":"INTO targets something that is not a variable (an IN parameter, a constant).","action":"Select into a local variable."},{"code":"PLS-00405","title":"Subquery not allowed in this context","cause":"A subquery was used in a PL/SQL expression (IF x IN (SELECT ...)).","action":"SELECT the value INTO a variable first, then test the variable."},{"code":"PLS-00428","title":"An INTO clause is expected in this SELECT statement","cause":"A SELECT in PL/SQL has no INTO (only cursors can select without INTO).","action":"Add INTO, or use a cursor FOR loop."},{"code":"PLS-00435","title":"DML statement without BULK In-BIND cannot be used inside FORALL","cause":"The statement inside FORALL does not reference the collection index.","action":"Use the collection(i) in the DML, or use a normal loop."},{"code":"PLS-00452","title":"Subprogram violates its associated pragma","cause":"A function marked with RESTRICT_REFERENCES or used with PRAGMA UDF/deterministic rules does something not allowed.","action":"Remove the side effect or the pragma."},{"code":"PLS-00487","title":"Invalid reference to variable","cause":"A field was used on something that is not a record (often a scalar treated as a record).","action":"Check the variable type."},{"code":"PLS-00488","title":"(name) must be a type","cause":"A %TYPE/variable declaration refers to something that is not a type.","action":"Use a real type or %TYPE of a column/variable."},{"code":"PLS-00642","title":"Local collection types not allowed in SQL statements","cause":"A collection type declared inside PL/SQL (before 12c) was used in SQL with TABLE().","action":"Create the type at schema level (CREATE TYPE ... AS TABLE OF) or upgrade to 12c+ for package-level types."},{"code":"PLS-00904","title":"Insufficient privilege to access object","cause":"The owner of the code lacks a privilege on a referenced object (role grants do not count).","action":"Grant the privilege directly to the code owner."},{"code":"PLS-00905","title":"Object is invalid","cause":"A called unit is invalid.","action":"Recompile it and check ALL_ERRORS for its errors."}];
